modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.OpAmps.VoltageFollower;
end Baseline;
model FINDING00936
  extends Modelica.Electrical.Analog.Examples.OpAmps.VoltageFollower(f=0);
end FINDING00936;
model FinalFINDING00936
  extends Modelica.Electrical.Analog.Examples.OpAmps.VoltageFollower(final f=0);
end FinalFINDING00936;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FINDING00936\n");
simulate(FINDING00936, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalFINDING00936\n");
simulate(FinalFINDING00936, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE FINDING00936\n");
system("./Baseline -override f=0 -r=FINDING00936_override.csv");
